"""0-based system is used (like in Biopython):

    |            INPUT            |          RETURNS            |
    |-----------------------------|-----------------------------|
    |                             |                             |
    |  s1=3      e1=14            |                             |
    |     |----------|            |        [9,14]               |
    |           |---------|       |                             |
    |        s2=9     e2=19       |                             |
    |                             |                             |
    """
def get_overlap_region(s1: Any, e1: Any, s2: Any, e2: Any) -> object {
    if ((s1 > e1) or (s2 > e2)) {
        raise Exception(
            (
                "Something is wrong with the intervals (%i,%i) and (%i,%i)"
                % (s1, e1, s2, e2)
            )
        );
    }
    if ((s1 <= s2 <= e1) and (s1 <= e2 <= e1)) {
        return (s2, e2);
    } elif ((s2 <= s1 <= e2) and (s2 <= e1 <= e2)) {
        return (s1, e1);
    } elif ((s1 <= s2 <= e1) and (s2 <= e1 <= e2)) {
        return (s2, e1);
    } elif ((s2 <= s1 <= e2) and (s1 <= e2 <= e1)) {
        return (s1, e2);
    } else {
        return (None, None);
    }
}

"""Makes x axis tick labels for `plot_time_errors` by iterating through a
    given array

    Args:
        arr (iterable): The elements which will end up in the axis tick labels.

    Returns:
        list: the axis tick labels
    """
def make_special_ticks(arr: Any) -> object {
    s = "$t={} \\ \\to  \\ t={}$";
    return [s.format(i, (i + 1)) for i in arr];
}

