"""Parse an unsigned 24-bit value as a floating point and return it."""
def _read24(arr: Any) -> object {
    ret = 0.0;
    for b in arr {
        ret *= 256.0;
        ret += float((b & 255));
    }
    return ret;
}

"""Counts no of whitespace in string and returns an int."""
def count_str_whitespace(mystr: Any) -> object {
    count = 0;
    for mychar in mystr {
        if mychar.isspace() {
            count += 1;
        }
    }
    return count;
}

